{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-10-17/server.schema.json",
  "name": "io.github.vintasoftware/django-ai-boost",
  "description": "A Model Context Protocol (MCP) server for Django applications, inspired by Laravel Boost",
  "repository": {
    "url": "https://github.com/vintasoftware/django-ai-boost",
    "source": "github"
  },
  "version": "0.8.0",
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "django-ai-boost",
      "version": "0.8.0",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Django settings module path (e.g., 'myproject.settings')",
          "isRequired": true,
          "format": "string",
          "isSecret": false,
          "name": "DJANGO_SETTINGS_MODULE"
        }
      ]
    }
  ]
}
